const D = { energy: .6, density: .5, scale: 1, speed: 1, nadir: .5, grain: .55, hue: 28, x: .5, y: .5, style: 'copper', act: 'survey', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const md = (a, n) => ((a % n) + n) % n;
// integer hash — finalize with >>> (>> sign-extends and caps the hash at 0.5)
function h2(ix, iy) { let h = (ix * 374761393 + iy * 668265263 + (P.seed | 0) * 1442695041) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
function h1(i) { return h2(i | 0, 0x5bd1); }
function vn(x, y) { const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy; const ux = fx*fx*(3-2*fx), uy = fy*fy*(3-2*fy); const a = h2(ix,iy), b = h2(ix+1,iy), c = h2(ix,iy+1), d = h2(ix+1,iy+1); return a + (b-a)*ux + (c-a)*uy + (a-b-c+d)*ux*uy; }
function fbm(x, y, oc) { let s = 0, am = .5, f = 1, nm = 0; for (let i = 0; i < oc; i++) { s += am * vn(x*f, y*f); nm += am; f *= 2.03; am *= .5; } return s / nm; }

const en = clp(P.energy, 0, 1), dens = clp(P.density, 0, 1), grain = clp(P.grain, 0, 1);
const W = width, H = height;
const BW = 256, BH = 200, rowB = BW * 4;

// ---- act dramaturgy ----
let objRate = .55 + dens * 1.5, pipe = 0, rippleAmt = 1;
if (P.act === 'wreck_field') { objRate = 1.6 + dens * 3.2; }
else if (P.act === 'pipeline') { pipe = 1; objRate = .3 + dens * .8; rippleAmt = 1.5; }

// ---- colour LUT (256 entries, rgb 0..255), cached on style+hue+seed ----
const lkey = P.style + '|' + Math.round(P.hue) + '|' + (P.seed | 0);
if (!S.lut || S.lkey !== lkey) {
  const MAPS = {
    copper:  [[.05,.03,.02],[.24,.11,.05],[.55,.28,.10],[.85,.57,.26],[.99,.90,.72]],
    survey:  [[.04,.04,.05],[.24,.24,.25],[.50,.50,.50],[.76,.76,.75],[.99,.99,.98]],
    ice:     [[.02,.04,.09],[.06,.17,.33],[.16,.42,.62],[.50,.74,.88],[.93,.98,1.0]],
    ironbow: [[.02,.01,.09],[.30,.05,.42],[.74,.20,.30],[.98,.60,.07],[1.0,.97,.72]],
    plate:   [[.09,.08,.07],[.20,.18,.16],[.42,.39,.35],[.72,.68,.61],[.94,.91,.85]]
  };
  const st = MAPS[P.style] || MAPS.copper;
  const rot = (md(P.hue - 28, 360)) * Math.PI / 180, cr = Math.cos(rot), sr = Math.sin(rot);
  const m = [ .213+cr*.787-sr*.213, .715-cr*.715-sr*.715, .072-cr*.072+sr*.928,
              .213-cr*.213+sr*.143, .715+cr*.285+sr*.140, .072-cr*.072-sr*.283,
              .213-cr*.213-sr*.787, .715-cr*.715+sr*.715, .072+cr*.928+sr*.072 ];
  const lut = new Uint8ClampedArray(256 * 3);
  for (let i = 0; i < 256; i++) {
    const f = i / 255 * 4, k = clp(Math.floor(f), 0, 3), fr2 = f - k;
    let r = st[k][0] + (st[k+1][0] - st[k][0]) * fr2;
    let g = st[k][1] + (st[k+1][1] - st[k][1]) * fr2;
    let b = st[k][2] + (st[k+1][2] - st[k][2]) * fr2;
    if (rot !== 0) { const nr = r*m[0]+g*m[1]+b*m[2], ng = r*m[3]+g*m[4]+b*m[5], nb = r*m[6]+g*m[7]+b*m[8]; r = nr; g = ng; b = nb; }
    lut[i*3] = clp(r, 0, 1) * 255; lut[i*3+1] = clp(g, 0, 1) * 255; lut[i*3+2] = clp(b, 0, 1) * 255;
  }
  S.lut = lut; S.lkey = lkey;
}
const lut = S.lut;

if (!S.g || S.gk !== BW) { if (S.g && S.g.remove) S.g.remove(); S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.gk = BW; S.fill = true; S.ping = 0; }
const g = S.g;
if (S.seedUsed !== P.seed) { S.seedUsed = P.seed; S.fill = true; }

// ---- seabed height field + backscatter ----
const NG = 0.05 + clp(P.nadir, 0, 1) * 0.17;   // nadir (water-column) gap as a fraction of half-swath
const ALT = 0.16;                              // towfish altitude above the bottom (sets shadow length)
const sc = 1 / clp(P.scale, .25, 2.6);
const dy = 0.011;

// objects live on an infinite procedural along-track stream: no bookkeeping, never converges
function objH(ax, ay) {
  let h = 0;
  const spacing = 0.42 / Math.max(objRate, .05);
  const i0 = Math.floor((ay - .55) / spacing), i1 = Math.floor((ay + .55) / spacing);
  for (let i = i0; i <= i1; i++) {
    const oy = i * spacing + (h1(i * 3 + 1) - .5) * spacing * .8;
    const ox = (h1(i * 3 + 2) - .5) * 1.75;
    const kind = h1(i * 3 + 3);
    const rad = (.02 + h1(i * 3 + 4) * .075) * (kind > .82 ? 2.4 : 1);
    const hh = (.02 + h1(i * 3 + 5) * .085) * (kind > .82 ? 1.7 : 1);
    const dx = ax - ox, dv = ay - oy;
    const d = Math.sqrt(dx * dx + dv * dv);
    if (d < rad) {
      if (kind > .82) {            // wreck: an angular hull with a spine
        const t = clp(1 - d / rad, 0, 1);
        h += hh * (t * t) * (1 + .5 * Math.sin(dv / rad * 7 + ox * 3)) * (Math.abs(dx) < rad * .45 ? 1.35 : .7);
      } else if (kind > .3) {      // boulder
        h += hh * Math.sqrt(clp(1 - (d / rad) * (d / rad), 0, 1));
      } else {                     // soft mound / sand wave crest
        const t = clp(1 - d / rad, 0, 1); h += hh * .45 * t * t * (3 - 2 * t);
      }
    }
  }
  if (pipe) {                       // a pipeline running along-track with free spans
    const px = .55 + .10 * Math.sin(ay * .35);
    const dxp = Math.abs(ax - px);
    if (dxp < .022) { const span = .5 + .5 * Math.sin(ay * 1.7); h += .05 * span * Math.sqrt(clp(1 - (dxp / .022) ** 2, 0, 1)); }
  }
  return h;
}
function bedH(ax, ay) {
  let h = 0.055 * (fbm(ax * 1.4 * sc + 11.3, ay * 1.4 * sc - 4.1, 3) - .5);          // sediment relief
  const rm = clp((fbm(ax * .8 * sc - 21.7, ay * .8 * sc + 9.4, 2) - .42) * 4.5, 0, 1); // ripple-field mask
  if (rm > 0.01) {                                                                     // sand ripples
    const ang = 1.05 + 1.5 * fbm(ax * .35 + 3.1, ay * .35 - 7.7, 2);
    const kx = Math.cos(ang), ky = Math.sin(ang);
    const wl = 26 * sc;
    h += rm * rippleAmt * .0125 * Math.sin((ax * kx + ay * ky) * wl);
  }
  return h + objH(ax, ay);
}

// ---- emit new pings (rows) ----
let want = Math.floor(K.t * (7.5 + clp(P.speed, 0, 3) * 5.5));
if (S.ping == null || want < S.ping) S.ping = want;      // tolerate t0 reset
let nRow = clp(want - S.ping, 0, 6);
if (S.fill) { nRow = BH; S.ping = want; }

if (nRow > 0) {
  g.loadPixels();
  const px = g.pixels;
  if (!S.fill) { px.copyWithin(nRow * rowB, 0, (BH - nRow) * rowB); }
  const half = BW / 2;
  const rowVals = new Float32Array(BW);
  for (let n = 0; n < nRow; n++) {
    const pingIdx = S.fill ? (want - (BH - 1 - n)) : (S.ping + (nRow - n));
    const ay = pingIdx * dy;
    // ---- one across-track ping: horizon march outward from nadir on each side ----
    for (let side = -1; side <= 1; side += 2) {
      let minTheta = 1e9, prevH = 0, prevR = NG;
      for (let s = 0; s < half; s++) {
        const r = NG + (1 - NG) * (s / (half - 1));
        const i = side < 0 ? Math.floor(half - 1 - s) : Math.floor(half + s);
        if (i < 0 || i >= BW) continue;
        if (s === 0 || r < NG + 1e-6) { rowVals[i] = -1; }
        const ax = side * r * 1.75;
        const hh = bedH(ax, ay);
        const theta = (ALT - hh) / Math.max(r, 1e-3);
        let v;
        if (theta >= minTheta - 1e-6) { v = 0.06 + 0.05 * h2(i * 7, pingIdx); }   // acoustic shadow
        else {
          minTheta = theta;
          const slope = (hh - prevH) / Math.max(r - prevR, 1e-4);                 // facing the fish = bright
          const graz = clp(1.15 - r * .55, .25, 1);
          let bs = 0.30 + 0.62 * clp(0.5 + slope * 2.6, 0, 1) * graz;
          bs *= (0.72 + 0.55 * fbm(ax * 6 * sc + 31, ay * 6 * sc + 17, 2));       // sediment hardness patches
          bs *= (1 - grain * 0.5) + grain * 1.0 * h2(i * 13 + 5, pingIdx * 3);    // Rayleigh speckle
          bs *= 0.55 + 0.9 * clp(r / 0.55, 0, 1);                                 // TVG
          v = bs;
        }
        prevH = hh; prevR = r;
        rowVals[i] = v;
      }
    }
    // water column: the nadir gap + the surface-return multipath line
    for (let i = 0; i < BW; i++) {
      const r = Math.abs(i - half + .5) / half;
      if (r < NG) {
        let v = 0.03 + 0.045 * h2(i * 3 + 1, pingIdx * 7);
        const sr = Math.abs(r - NG * 0.62);
        if (sr < 0.012) v += 0.5 * (1 - sr / 0.012);
        rowVals[i] = v;
      }
    }
    const rb = n * rowB;
    const gainv = 0.55 + en * 1.25;
    for (let i = 0; i < BW; i++) {
      let v = rowVals[i] * gainv;
      if (P.style === 'plate') v = clp((v - .42) * 2.6 + .42, 0, 1);
      const ci = clp(Math.round(clp(v, 0, 1) * 255), 0, 255) * 3;
      const o = rb + i * 4;
      px[o] = lut[ci]; px[o+1] = lut[ci+1]; px[o+2] = lut[ci+2]; px[o+3] = 255;
    }
  }
  g.updatePixels();
  S.ping = want; S.fill = false;
}

// =================== composite ===================
const u = Math.min(W, H);
noStroke();
push();
translate((P.x - .5) * W * .35, (P.y - .5) * H * .35);
image(g, -W * .01, -H * .01, W * 1.02, H * 1.02);
pop();

const ink = P.style === 'plate' || P.style === 'survey' ? [30, 12, 12] : [40, 20, 96];
const IH = md(ink[0] + (P.hue - 28), 360);
textFont('Courier New');
textSize(clp(u * .0105, 6, 20));

// nadir centreline + across-track range scale
const cxs = W * .5 + (P.x - .5) * W * .35;
stroke(IH, 10, ink[2], 28); strokeWeight(1);
line(cxs, 0, cxs, H);
for (let k = 1; k <= 4; k++) {
  for (let sgn = -1; sgn <= 1; sgn += 2) {
    const xx = cxs + sgn * (NG + (1 - NG) * k / 4) * W * .51;
    stroke(IH, 10, ink[2], 22); line(xx, 0, xx, H);
    noStroke(); fill(IH, 12, ink[2], 62);
    textAlign(CENTER, TOP); text((k * 25) + 'm', xx, u * .012);
  }
}
// fix marks: a tick + timestamp every 50 pings, scrolling with the record
const rowPx = H / BH;
for (let k = 0; k < 6; k++) {
  const fixPing = Math.floor(S.ping / 50) * 50 - k * 50;
  const yy = (S.ping - fixPing) * rowPx * 1.02;
  if (yy < 0 || yy > H) continue;
  stroke(IH, 12, ink[2], 50); strokeWeight(1); line(0, yy, u * .022, yy); line(W - u * .022, yy, W, yy);
  noStroke(); fill(IH, 12, ink[2], 58); textAlign(LEFT, CENTER);
  const sec = fixPing * 0.4;
  text('F' + String(Math.abs(fixPing / 50) % 1000).padStart(3, '0') + '  ' + String(Math.floor(md(sec / 60, 60))).padStart(2, '0') + ':' + String(Math.floor(md(sec, 60))).padStart(2, '0'), u * .028, yy);
}
// header readouts — the instrument's voice
noStroke(); fill(IH, 12, ink[2], 86); textAlign(LEFT, TOP);
text('SIDE SCAN  ·  100 kHz  ·  RANGE 100 m', u * .028, H - u * .048);
fill(IH, 12, ink[2], 66);
text('ALT ' + (ALT * 100).toFixed(1) + ' m   SOG ' + (2.4 + .6 * Math.sin(K.t * .11)).toFixed(1) + ' kn   HDG ' + String(Math.round(md(47 + 9 * Math.sin(K.t * .043), 360))).padStart(3, '0'), u * .028, H - u * .030);
textAlign(RIGHT, TOP);
fill(IH, 12, ink[2], 76);
text('PING ' + String(S.ping % 100000).padStart(5, '0'), W - u * .028, H - u * .048);
fill(IH, 12, ink[2], 56);
text(P.act.toUpperCase().replace('_', ' '), W - u * .028, H - u * .030);

// paper/record vignette (broad, soft — no flicker)
blendMode(MULTIPLY);
noFill(); stroke(0, 0, 40, 34); strokeWeight(u * .10);
rect(-u * .05, -u * .05, W + u * .1, H + u * .1);
blendMode(BLEND);
if (P.alpha < 100) { noStroke(); fill(0, 0, 6, 100 - clp(P.alpha, 0, 100)); rect(0, 0, W, H); }
